css:
.sl-gallery-interactive-map { padding: 5rem 0; background-color: var(--smartlearn-card-bg); }
.sl-gallery-interactive-map .text-center { text-align: center; }
.sl-gallery-interactive-map .sl-mb-12 { margin-bottom: 3rem; }
.sl-gallery-interactive-map .sl-section-title { font-size: 2.25rem; font-weight: 700; color: var(--smartlearn-text); margin-bottom: 0.5rem; }
.sl-gallery-interactive-map .sl-section-subtitle { font-size: 1.125rem; color: var(--smartlearn-text-muted); }
.sl-gallery-interactive-map .sl-map-container { position: relative; max-width: 1000px; margin: 0 auto; border-radius: 1rem; overflow: hidden; border: 1px solid var(--smartlearn-card-border, rgba(0,0,0,0.05)); box-shadow: 0 15px 30px rgba(0,0,0,0.05); }
.sl-gallery-interactive-map .sl-map-base { width: 100%; display: block; object-fit: cover; aspect-ratio: 16/9; }
.sl-gallery-interactive-map .sl-map-pin { position: absolute; width: 32px; height: 32px; background: transparent; border: none; cursor: pointer; display: flex; align-items: center; justify-content: center; transform: translate(-50%, -50%); outline: none; z-index: 10; }
.sl-gallery-interactive-map .sl-pin-dot { width: 16px; height: 16px; background-color: var(--smartlearn-primary); border-radius: 50%; box-shadow: 0 2px 5px rgba(0,0,0,0.3); border: 2px solid #fff; z-index: 2; transition: transform 0.2s ease; }
.sl-gallery-interactive-map .sl-map-pin:hover .sl-pin-dot, .sl-gallery-interactive-map .sl-map-pin:focus-visible .sl-pin-dot, .sl-gallery-interactive-map .sl-pin-active .sl-pin-dot { transform: scale(1.3); }
.sl-gallery-interactive-map .sl-pin-pulse { position: absolute; width: 100%; height: 100%; background-color: var(--smartlearn-primary); border-radius: 50%; opacity: 0.5; z-index: 1; animation: sl-pulse 2s infinite; }
@keyframes sl-pulse { 0% { transform: scale(1); opacity: 0.7; } 100% { transform: scale(2.5); opacity: 0; } }
@media (prefers-reduced-motion: reduce) { .sl-pin-pulse { animation: none; display: none; } }
.sl-gallery-interactive-map .sl-map-info-panel { position: absolute; bottom: 2rem; left: 2rem; background: var(--smartlearn-bg); padding: 1.5rem; border-radius: 0.75rem; box-shadow: 0 10px 25px rgba(0,0,0,0.15); border: 1px solid var(--smartlearn-card-border, rgba(0,0,0,0.05)); max-width: 300px; opacity: 0; visibility: hidden; transform: translateY(10px); transition: all 0.3s ease; z-index: 20; }
.sl-gallery-interactive-map .sl-map-info-panel.sl-show { opacity: 1; visibility: visible; transform: translateY(0); }
.sl-gallery-interactive-map .sl-info-title { font-size: 1.125rem; font-weight: 700; color: var(--smartlearn-text); margin-bottom: 0.5rem; }
.sl-gallery-interactive-map .sl-info-desc { font-size: 0.875rem; color: var(--smartlearn-text-muted); margin: 0; line-height: 1.5; }
@media (max-width: 767px) {
    .sl-gallery-interactive-map .sl-map-container { display: flex; flex-direction: column; aspect-ratio: auto; }
    .sl-gallery-interactive-map .sl-map-base { aspect-ratio: 4/3; }
    .sl-gallery-interactive-map .sl-map-pin { display: none; /* Hide pins on mobile, show list instead */ }
    .sl-gallery-interactive-map .sl-map-info-panel { position: static; max-width: 100%; opacity: 1; visibility: visible; transform: none; box-shadow: none; border-radius: 0; border: none; border-bottom: 1px solid var(--smartlearn-card-border, rgba(0,0,0,0.05)); display: block !important; }
}

js:
(function() {
    const root = document.querySelector('.sl-gallery-interactive-map');
    if (!root) return;
    const pins = root.querySelectorAll('.sl-map-pin');
    const panels = root.querySelectorAll('.sl-map-info-panel');
    if(!pins.length) return;

    pins.forEach(pin => {
        pin.addEventListener('click', () => {
            if(document.body.classList.contains('sl-editor-mode')) return;
            const targetId = pin.getAttribute('data-target');

            pins.forEach(p => p.classList.remove('sl-pin-active'));
            pin.classList.add('sl-pin-active');

            panels.forEach(panel => {
                if(panel.id === targetId) {
                    panel.classList.add('sl-show');
                } else {
                    panel.classList.remove('sl-show');
                }
            });
        });
    });
})();
